-- SCM_MGR.SCM_MAINT_LOG definition

CREATE TABLE "SCM_MGR"."SCM_MAINT_LOG" 
   (	"LOG_SEQ" NUMBER NOT NULL ENABLE, 
	"EXEC_TYPE" VARCHAR2(50 CHAR) NOT NULL ENABLE, 
	"START_TIME" DATE NOT NULL ENABLE, 
	"END_TIME" DATE, 
	"ELAPSED_SEC" NUMBER, 
	"TARGET_OWNER" VARCHAR2(30 CHAR), 
	"SUCCESS_CNT" NUMBER DEFAULT 0, 
	"FAIL_CNT" NUMBER DEFAULT 0, 
	"STATUS" VARCHAR2(10 CHAR) DEFAULT 'RUNNING', 
	"REMARKS" VARCHAR2(4000 CHAR), 
	"REG_DATE" DATE DEFAULT SYSDATE     -- 등록 일시
, 
	 CONSTRAINT "PK_SCM_MAINT_LOG" PRIMARY KEY ("LOG_SEQ", "START_TIME")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "TS_SCM_PX01"  LOCAL
 (PARTITION "SYS_P3153" NOCOMPRESS 
  PCTFREE 10 INITRANS 2 MAXTRANS 255 LOGGING 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "TS_SCM_PX01" )  ENABLE
   ) PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "TS_SCM_PD01" 
  PARTITION BY RANGE ("START_TIME") INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) 
 (PARTITION "SYS_P3153"  VALUES LESS THAN (TO_DATE(' 2026-03-01 00:00:00', 'SYYYY-MM-DD HH24:MI:SS', 'NLS_CALENDAR=GREGORIAN')) SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "TS_SCM_PD01" ) ;

CREATE INDEX "SCM_MGR"."IDX01_SCM_MAINT_LOG" ON "SCM_MGR"."SCM_MAINT_LOG" ("EXEC_TYPE", "START_TIME") 
  PCTFREE 10 INITRANS 2 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "TS_SCM_PX01"  LOCAL
 (PARTITION "SYS_P3153" NOCOMPRESS 
  PCTFREE 10 INITRANS 2 MAXTRANS 255 LOGGING 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "TS_SCM_PX01" ) ;

